// Build per-platform publish jobs
const content = $('Fetch Content & Business').first().json;
const creds = $('Fetch Platform Credentials').all().map(i => i.json);
const variants = typeof content.variants === 'string' ? JSON.parse(content.variants) : content.variants;

const jobs = [];
const credMap = {};
creds.forEach(c => {
  try {
    credMap[c.platform] = JSON.parse(c.credentials_encrypted);
  } catch(e) {
    credMap[c.platform] = c.credentials_encrypted;
  }
});

for (const [platform, variant] of Object.entries(variants)) {
  if (platform === 'image_prompt') continue; // skip meta field
  if (!credMap[platform]) continue; // skip platforms without credentials

  jobs.push({
    content_id: content.id,
    business_id: content.business_id,
    platform,
    variant,
    credentials: credMap[platform],
    image_url: content.image_url || null
  });
}

return jobs;

// Publish to X/Twitter using API v2
// OAuth 1.0a signing is handled by n8n credential (configure in n8n UI)
const job = $input.first().json;
const creds = job.credentials;
const text = job.variant.text + (job.variant.hashtags ? ' ' + job.variant.hashtags.map(h => '#' + h).join(' ') : '');

try {
  // Use n8n's built-in OAuth 1.0a signing via HTTP Request after this Code node
  // This prepares the payload; the actual POST is done by the next HTTP Request node
  // OR do it inline with fetch + oauth-1.0a signing:
  const crypto = require('crypto');
  const oauth = {
    consumer_key: creds.api_key,
    consumer_secret: creds.api_secret,
    token: creds.access_token,
    token_secret: creds.access_token_secret,
  };

  const timestamp = Math.floor(Date.now() / 1000).toString();
  const nonce = crypto.randomBytes(16).toString('hex');
  const method = 'POST';
  const url = 'https://api.twitter.com/2/tweets';

  // OAuth 1.0a signature base
  const params = {
    oauth_consumer_key: oauth.consumer_key,
    oauth_nonce: nonce,
    oauth_signature_method: 'HMAC-SHA1',
    oauth_timestamp: timestamp,
    oauth_token: oauth.token,
    oauth_version: '1.0',
  };

  const paramStr = Object.keys(params).sort().map(k => `${encodeURIComponent(k)}=${encodeURIComponent(params[k])}`).join('&');
  const baseStr = `${method}&${encodeURIComponent(url)}&${encodeURIComponent(paramStr)}`;
  const signingKey = `${encodeURIComponent(oauth.consumer_secret)}&${encodeURIComponent(oauth.token_secret)}`;
  const signature = crypto.createHmac('sha1', signingKey).update(baseStr).digest('base64');

  const authHeader = `OAuth oauth_consumer_key="${encodeURIComponent(oauth.consumer_key)}", oauth_nonce="${nonce}", oauth_signature="${encodeURIComponent(signature)}", oauth_signature_method="HMAC-SHA1", oauth_timestamp="${timestamp}", oauth_token="${encodeURIComponent(oauth.token)}", oauth_version="1.0"`;

  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'Authorization': authHeader,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ text }),
  });

  const result = await response.json();
  const postId = result.data?.id;

  return {
    content_id: job.content_id,
    business_id: job.business_id,
    platform: 'x',
    status: response.ok ? 'success' : 'failed',
    post_id: postId || null,
    post_url: postId ? `https://x.com/i/status/${postId}` : null,
    error_message: response.ok ? null : JSON.stringify(result),
  };
} catch (e) {
  return {
    content_id: job.content_id,
    business_id: job.business_id,
    platform: 'x',
    status: 'failed',
    post_id: null,
    post_url: null,
    error_message: e.message,
  };
}

// Instagram Graph API — Two-step publish
const job = $input.first().json;
const creds = job.credentials;
const caption = (job.variant.caption || '') + '\n\n' + (job.variant.hashtags || []).map(h => '#' + h).join(' ');

try {
  // Step 1: Create media container
  const createUrl = `https://graph.instagram.com/v21.0/${creds.ig_user_id}/media`;
  const createBody = new URLSearchParams({
    image_url: job.image_url || '',
    caption: caption,
    access_token: creds.access_token,
  });

  const createResp = await fetch(createUrl, { method: 'POST', body: createBody });
  const createData = await createResp.json();

  if (createData.error || !createData.id) {
    return {
      content_id: job.content_id, business_id: job.business_id, platform: 'instagram',
      status: 'failed', post_id: null, post_url: null,
      error_message: createData.error?.message || 'Failed to create media container',
    };
  }

  // Wait for container to be ready (poll status)
  let ready = false;
  for (let i = 0; i < 10; i++) {
    await new Promise(r => setTimeout(r, 3000));
    const statusResp = await fetch(`https://graph.instagram.com/v21.0/${createData.id}?fields=status_code&access_token=${creds.access_token}`);
    const statusData = await statusResp.json();
    if (statusData.status_code === 'FINISHED') { ready = true; break; }
    if (statusData.status_code === 'ERROR') {
      return { content_id: job.content_id, business_id: job.business_id, platform: 'instagram', status: 'failed', error_message: 'Container processing failed' };
    }
  }

  if (!ready) {
    return { content_id: job.content_id, business_id: job.business_id, platform: 'instagram', status: 'failed', error_message: 'Container timed out' };
  }

  // Step 2: Publish
  const publishUrl = `https://graph.instagram.com/v21.0/${creds.ig_user_id}/media_publish`;
  const publishBody = new URLSearchParams({
    creation_id: createData.id,
    access_token: creds.access_token,
  });

  const publishResp = await fetch(publishUrl, { method: 'POST', body: publishBody });
  const publishData = await publishResp.json();

  return {
    content_id: job.content_id, business_id: job.business_id, platform: 'instagram',
    status: publishData.id ? 'success' : 'failed',
    post_id: publishData.id || null,
    post_url: publishData.id ? `https://www.instagram.com/p/${publishData.id}/` : null,
    error_message: publishData.error?.message || null,
  };
} catch (e) {
  return { content_id: job.content_id, business_id: job.business_id, platform: 'instagram', status: 'failed', error_message: e.message };
}

// LinkedIn Posts API
const job = $input.first().json;
const creds = job.credentials;
const commentary = (job.variant.commentary || job.variant.text || '') + '\n\n' + (job.variant.hashtags || []).map(h => '#' + h).join(' ');

try {
  const body = {
    author: creds.author_urn,
    commentary: commentary,
    visibility: 'PUBLIC',
    distribution: { feedDistribution: 'MAIN_FEED', targetEntities: [], thirdPartyDistributionChannels: [] },
    lifecycleState: 'PUBLISHED',
    isReshareDisabledByAuthor: false,
  };

  const response = await fetch('https://api.linkedin.com/rest/posts', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${creds.access_token}`,
      'Content-Type': 'application/json',
      'X-Restli-Protocol-Version': '2.0.0',
      'LinkedIn-Version': '202602',
    },
    body: JSON.stringify(body),
  });

  // LinkedIn returns 201 with x-restli-id header for the post URN
  const postUrn = response.headers.get('x-restli-id') || '';
  const postId = postUrn.split(':').pop();

  return {
    content_id: job.content_id, business_id: job.business_id, platform: 'linkedin',
    status: response.status === 201 ? 'success' : 'failed',
    post_id: postUrn || null,
    post_url: postId ? `https://www.linkedin.com/feed/update/${postUrn}/` : null,
    error_message: response.status !== 201 ? `HTTP ${response.status}` : null,
  };
} catch (e) {
  return { content_id: job.content_id, business_id: job.business_id, platform: 'linkedin', status: 'failed', error_message: e.message };
}

// Facebook Graph API
const job = $input.first().json;
const creds = job.credentials;
const message = (job.variant.message || job.variant.text || '') + '\n\n' + (job.variant.hashtags || []).map(h => '#' + h).join(' ');

try {
  let url, body;

  if (job.image_url) {
    // Photo post
    url = `https://graph.facebook.com/v21.0/${creds.page_id}/photos`;
    body = new URLSearchParams({
      url: job.image_url,
      caption: message,
      access_token: creds.page_access_token,
    });
  } else {
    // Text-only post
    url = `https://graph.facebook.com/v21.0/${creds.page_id}/feed`;
    body = new URLSearchParams({
      message: message,
      access_token: creds.page_access_token,
    });
  }

  const response = await fetch(url, { method: 'POST', body });
  const data = await response.json();

  return {
    content_id: job.content_id, business_id: job.business_id, platform: 'facebook',
    status: data.id ? 'success' : 'failed',
    post_id: data.id || data.post_id || null,
    post_url: data.id ? `https://www.facebook.com/${data.id}` : null,
    error_message: data.error?.message || null,
  };
} catch (e) {
  return { content_id: job.content_id, business_id: job.business_id, platform: 'facebook', status: 'failed', error_message: e.message };
}

// TikTok Content Posting API — Photo post (image-based)
const job = $input.first().json;
const creds = job.credentials;
const title = (job.variant.title || '') + ' ' + (job.variant.hashtags || []).map(h => '#' + h).join(' ');

try {
  if (!job.image_url) {
    return { content_id: job.content_id, business_id: job.business_id, platform: 'tiktok', status: 'failed', error_message: 'TikTok requires image or video content' };
  }

  // TikTok photo publish flow
  const initResp = await fetch('https://open.tiktokapis.com/v2/post/publish/content/init/', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${creds.access_token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      post_info: {
        title: title.substring(0, 150),
        privacy_level: 'SELF_ONLY', // Start private, can be changed
        disable_comment: false,
        auto_add_music: true,
      },
      source_info: {
        source: 'PULL_FROM_URL',
        photo_cover_index: 0,
        photo_images: [job.image_url],
      },
      post_mode: 'DIRECT_POST',
      media_type: 'PHOTO',
    }),
  });

  const initData = await initResp.json();
  const publishId = initData.data?.publish_id;

  return {
    content_id: job.content_id, business_id: job.business_id, platform: 'tiktok',
    status: publishId ? 'success' : 'failed',
    post_id: publishId || null,
    post_url: null, // TikTok doesn't return direct URL immediately
    error_message: initData.error?.message || (publishId ? null : 'No publish_id returned'),
  };
} catch (e) {
  return { content_id: job.content_id, business_id: job.business_id, platform: 'tiktok', status: 'failed', error_message: e.message };
}

// Auto-trigger dubbing for each configured language
const content = $('Fetch Content & Business').first().json;
const videoLangs = content.video_languages || [];
const hasVideo = !!content.video_url;

if (!hasVideo || videoLangs.length <= 1) {
  // No video or only source language — skip dubbing
  return [{ json: { dubbing: 'skipped', reason: hasVideo ? 'only source language' : 'no video' } }];
}

const results = [];
for (const lang of videoLangs) {
  if (lang === 'en') continue; // Skip source language
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: `${$env.API_BASE_URL}/api/dubbing/start`,
      headers: { 'Authorization': `Bearer ${$env.ENGINE_JWT}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ content_id: content.id, target_language: lang }),
    });
    results.push({ lang, status: 'started', dubbing_id: res.dubbing_id });
  } catch(e) {
    results.push({ lang, status: 'failed', error: e.message });
  }
}
return [{ json: { dubbing: 'triggered', jobs: results } }];
